using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace BuMatrixSecurityRoleAssigner
{
    // This is the entry point XrmToolBox discovers via MEF. It just hands back the UI control.
    [Export(typeof(IXrmToolBoxPlugin))]
    [ExportMetadata("Name", "BU Matrix Security Role Assigner")]
    [ExportMetadata("Description", "Bulk-assign or remove security roles for one or more teams. Built for the modernized (matrix) business-units model; a classic-BU mode resolves each role to the correct copy in the team's business unit.")]
    [ExportMetadata("SmallImageBase64", "")]
    [ExportMetadata("BigImageBase64", "")]
    [ExportMetadata("BackgroundColor", "White")]
    [ExportMetadata("PrimaryFontColor", "Black")]
    [ExportMetadata("SecondaryFontColor", "DarkGray")]
    public class BuMatrixSecurityRoleAssignerPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new BuMatrixSecurityRoleAssignerControl();
        }
    }
}
